const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const photos=[['friends','小林','一起吃饭，就是好周末'],['table','阿文','开饭啦'],['dinner','熊猫','今晚的现场'],['food','小林','再来一份'],['friends','熊猫','好久不见'],['table','阿文','留住这一刻']];
let nickname='熊猫',filter='全部',mode='照片',voted=false,choice=0,paused=false,closed=false,localPhotos=[],notes=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>'<span class="brand"><span class="logo">▥</span> RoomDeck</span>';
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3200)}
function modal(html){document.querySelector('#dialogbody').innerHTML=html;dialog.showModal()}
function nav(view){location.hash=view}
function cards(count=4){return [...localPhotos,...photos.map(p=>({src:'assets/'+p[0]+'.jpg',name:p[1],title:p[2]}))].slice(0,count).map((p,i)=>`<article class="photo"><button onclick="detail(${i})" aria-label="查看照片：${esc(p.title)}"><img src="${p.src}" alt="${esc(p.title)}"></button><div class="row between"><span class="row"><span class="avatar">${esc(p.name[0])}</span>${esc(p.name)}</span><small>${i<localPhotos.length?'本地预览':'刚刚'}</small></div></article>`).join('')}
function detail(i){const p=[...localPhotos,...photos.map(p=>({src:'assets/'+p[0]+'.jpg',name:p[1],title:p[2]}))][i];modal(`<h2>${esc(p.title)}</h2><img src="${p.src}" alt="${esc(p.title)}" style="width:100%;max-height:55vh;object-fit:contain;margin-top:20px;border-radius:8px"><p>${esc(p.name)} 分享 · 示例照片</p><button class="primary full" onclick="dialog.close();toast('原型演示：照片已加入大屏精选')">精选到大屏（演示）</button>`)}
function bottom(){return `<nav class="bottom-nav" aria-label="房间导航"><button class="${filter==='全部'?'selected':''}" onclick="filter='全部';nav('guest');render()"><b>⌂</b>现场</button><button class="${filter==='照片'?'selected':''}" onclick="filter='照片';nav('guest');render()"><b>▧</b>照片</button><button class="share" onclick="share()" aria-label="分享内容"><b>＋</b>分享</button><button class="${filter==='资料'?'selected':''}" onclick="filter='资料';nav('guest');render()"><b>▤</b>资料</button></nav>`}
function phone(content,footer=true){return `<div class="phone"><div class="island"></div><div class="statusbar"><span>19:41</span><span>▂▄▆ · ▰</span></div><div class="phone-content">${content}</div>${footer?bottom():''}</div>`}
function stage(title,desc,points,content){return `<section class="phone-stage"><aside class="design-note"><div class="mini-rule"></div><span class="tag">RoomDeck · 界面设计</span><h1>${title}</h1><p>${desc}</p><ul>${points.map(p=>`<li>${p}</li>`).join('')}</ul><a class="doc-link" href="../docs/RoomDeck-开发设计文档.html" target="_blank">阅读完整产品与开发文档 ↗</a></aside>${content}</section>`}
function join(){return stage('扫一下，<br>就在一起。','不用下载 App，也不用建立新账号。这个临时房间，只属于此刻的相聚。',['先看清活动，再输入昵称','可见范围与保留时间提前说明','再次打开，继续使用原有身份'],phone(`${brand()}<img class="welcome-cover" src="assets/friends.jpg" alt="朋友围坐在餐桌旁"><span class="tag">邀请你加入</span><h1 style="margin:14px 0 8px">周末小聚</h1><p class="muted">今晚的照片和小事，都放在这里。</p><div class="row" style="margin-top:16px"><span class="live">12 人在线</span><small>熊猫发起 · 房间 7K3PM9</small></div><form onsubmit="event.preventDefault();enterRoom()"><label class="field" for="nickname">怎么称呼你？</label><input id="nickname" maxlength="20" value="${esc(nickname)}" required autocomplete="nickname"><div class="notice">分享的内容对房间成员可见，精选照片会出现在现场大屏。活动结束后保留 24 小时。</div><button class="primary full">进入房间 →</button></form><p style="text-align:center;margin-top:16px"><small>无需注册 · 本页为设计演示</small></p>`,false))}
function enterRoom(){nickname=document.querySelector('#nickname').value.trim();if(!nickname){toast('请输入昵称');return}nav('guest')}
function resources(){return `<div class="resource"><span class="tag">文件</span><h3 style="margin-top:9px">周末菜单.pdf</h3><p>1.8 MB · 熊猫分享</p><button style="margin-top:10px" onclick="toast('这是示例文件，未提供实际下载')">下载文件</button></div><div class="resource"><span class="tag">链接</span><h3 style="margin-top:9px">下次聚会想去的地方</h3><p>example.com · 示例链接</p></div>${notes.map(n=>`<div class="resource"><span class="tag">便签 · 本地演示</span><h3 style="margin-top:8px">${esc(n)}</h3><p>${esc(nickname)} · 刚刚</p></div>`).join('')}`}
function guest(){return stage('现场发生的，<br>大家都看得见。','把主要位置留给照片和正在发生的事，分享始终在拇指够得到的地方。',['照片、资料按需筛选','新内容不打断当前浏览','分享成功与上屏状态分开反馈'],phone(`<div class="row between">${brand()}<span class="avatar">${esc(nickname[0])}</span></div><div class="roomhead"><div class="row between"><h1>周末小聚</h1><span class="live">12 人在线</span></div><p>房间 7K3PM9 · 今晚 23:00 结束</p></div><article class="pinned"><div class="row between"><span class="tag">主持人精选</span><small>熊猫 · 19:32</small></div><h3 style="margin-top:10px">好久不见，先好好吃顿饭。</h3><p>拍到的合照记得放进来，结束后一起带走。</p></article><div class="tabs">${['全部','照片','资料'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}<small style="margin-left:auto">最新优先</small></div>${filter==='资料'?resources():`<div class="photo-grid">${cards(6)}</div>`}`))}
function host(){return `<div class="host-layout"><aside class="sidebar">${brand()}<button onclick="toast('当前展示一个示例房间')">▦　我的房间</button><div class="side-label">周末小聚</div><button class="sel" onclick="filter='全部';render()">◉　现场控制</button><button onclick="filter='资料';render()">▤　共享资料</button><button onclick="members()">♧　参与者 <span style="float:right">12</span></button><button onclick="settings()">⚙　房间设置</button><div class="side-bottom"><div class="row"><span class="avatar">熊</span><div>熊猫<small style="display:block">主持人</small></div></div><div style="margin-top:24px"><small>本次房间空间</small><div class="quota"><span></span></div><small>638 MB / 2 GB</small></div></div></aside><section class="host-main"><div class="breadcrumbs">我的房间　/　周末小聚　/　现场控制</div><div class="row between host-title"><div><div class="row"><h1>周末小聚</h1><span class="tag">${closed?'已结束':'进行中'}</span></div><p>2026 年 9 月 9 日 · 18:00–23:00　<span class="live">12 人在线</span></p></div><div class="row"><button onclick="invite()">▦　邀请加入</button><button class="primary" onclick="nav('display')">打开大屏 ↗</button></div></div><div class="host-columns"><div><section class="panel host-gallery"><div class="section-head"><h2>${filter==='资料'?'共享资料':'大家的现场'}</h2><button onclick="share()">＋ 添加内容</button></div><div class="statsline"><span><b>48</b> 张照片</span><span><b>3</b> 份文件</span><span><b>5</b> 条便签与链接</span></div><div class="tabs">${['全部','照片','资料'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}<small style="margin-left:auto">新照片需精选后上屏</small></div>${filter==='资料'?resources():`<div class="photo-grid">${cards(6)}</div>`}<div class="rule"></div><div class="row between"><small>房间成员可见 · 已精选 8 张照片</small><button onclick="toast('原型演示：已将当前照片设为精选')">管理大屏精选</button></div></section><div class="row between" style="margin-top:23px"><small>结束后保留 24 小时，可导出全部内容。</small><button onclick="closeRoom()">结束房间</button></div></div><aside class="stack" style="align-content:start"><section class="panel"><div class="row between"><h2>现场大屏</h2><span class="live">演示在线</span></div><div class="display-mini"><img src="assets/friends.jpg" alt="大屏当前照片预览"><div>${mode==='照片'?'周末小聚':mode} <small>· ${paused?'已暂停':'正在展示'}</small></div></div><div class="modes">${['欢迎','照片','精选'].map(m=>`<button class="${mode===m?'active':''}" onclick="mode='${m}';render();toast('原型演示：大屏模式已切换')">${m}</button>`).join('')}</div><div class="row"><button style="flex:1" onclick="paused=!paused;render()">${paused?'▶ 继续轮播':'Ⅱ 暂停轮播'}</button><button onclick="mode='黑屏';render();toast('原型大屏已设为黑屏')">黑屏</button></div><div class="row between" style="margin-top:15px"><small>每张停留 10 秒</small><small>精选模式</small></div></section><section class="panel"><h2>刚刚发生</h2><div class="timeline"><div class="row"><span class="avatar">林</span><div>小林 分享了 2 张照片<small>1 分钟前</small></div></div><div class="row"><span class="avatar">文</span><div>阿文 加入了房间<small>3 分钟前</small></div></div><div class="row"><span class="avatar">熊</span><div>你更新了精选便签<small>9 分钟前</small></div></div></div></section></aside></div></section></div>`}
function display(){if(mode==='黑屏')return `<section class="screen-stage" style="min-height:100vh;display:grid;place-items:center"><p class="muted">画面已暂停展示</p></section>`;return `<section class="screen-stage"><header class="row between">${brand()}<div class="row"><span class="tag">${paused?'轮播已暂停':'此刻，共享中'}</span><span class="muted">12 人在这里</span></div></header><div class="screen-main"><div class="screen-photo">${mode==='照片'?`<img src="assets/friends.jpg" alt="朋友们围坐在一起分享晚餐"><div class="screen-caption"><span>一起吃饭，就是好周末。</span><small>小林 分享　·　03 / 08</small></div>`:`<div class="screen-welcome"><div><h1>${mode==='黑屏'?'画面已暂停展示':mode==='精选'?'好久不见，先好好吃顿饭。':'欢迎来到周末小聚'}</h1><p>${mode==='黑屏'?'等待主持人继续':'今晚的照片和小事，都放在这里。'}</p></div></div>`}</div><aside class="screen-invite"><div><span class="tag">今晚的共享房间</span><h1>周末小聚</h1><p>扫一下，加入我们。</p></div><div><img class="qr" src="assets/qr.svg" alt="示例二维码，指向演示地址"><div class="room-code">7K3P M9</div><small>示例二维码 · 非真实活动入口</small></div></aside></div><footer class="screen-footer"><span>让此刻的照片，成为大家的回忆。</span><span>照片由主持人精选　 ·　 23:00 结束</span><button style="background:transparent;color:white;min-height:32px;padding:3px 10px" onclick="document.documentElement.requestFullscreen?.().catch(()=>toast('当前浏览器无法进入全屏'))">全屏 ⛶</button></footer></section>`}
function poll(){let names=['去公园散散步','找一家咖啡馆','继续在这里聊天'],counts=[8,3,1];return stage('下一站去哪，<br>一起决定。','投票融入活动现场。参与者知道自己是否已提交，也知道结果何时可见。',['单选、多选规则明确','结果可实时展示在大屏','V0.2 扩展，不计入首版范围'],phone(`<div class="row between"><button onclick="nav('guest')" style="border:0;padding:0">← 返回现场</button><span class="tag">V0.2 · 设计预览</span></div><div class="poll-hero"><span class="tag">正在投票 · 还剩 18 分钟</span><h1>吃完饭，<br>下一站去哪？</h1><p>熊猫发起 · 匿名单选 · 投票后显示结果</p></div>${names.map((n,i)=>`<button class="poll-option ${choice===i?'chosen':''}" onclick="choice=${i};render()"><div class="row between"><span>${choice===i?'◉':'○'}　${n}</span>${voted?`<b>${counts[i]} 票</b>`:''}</div>${voted?`<div class="bar"><span style="width:${counts[i]/12*100}%"></span></div>`:''}</button>`).join('')}<button class="primary full" style="margin-top:20px" onclick="voted=true;render();toast('演示投票已提交，结果为示例统计')">${voted?'更新我的选择':'提交投票'}</button><div class="notice">${voted?'✓ 已记录你的演示选择。截止前可改票，统计为设计示例。':'提交前不会显示结果。截止前可以修改选择。'}</div><div class="row"><span class="avatar">熊</span><small>12 人已参与 · 无需公开你的选择</small></div>`))}
function end(){return stage('活动会结束，<br>回忆可以带走。','明确告诉大家哪些内容还可以查看，以及它们会在什么时候删除。',['结束与删除分开操作','导出有清晰的进度与失败反馈','用具体日期表达保留期限'],phone(`${brand()}<div class="end-icon">✓</div><span class="tag">活动已结束</span><h1 style="margin-top:14px">今晚，收获满满。</h1><p class="muted" style="margin-top:10px">周末小聚 · 9 月 9 日</p><div class="strip"><img src="assets/friends.jpg" alt="聚会合影"><img src="assets/table.jpg" alt="晚餐"><img src="assets/food.jpg" alt="美食"></div><div class="end-grid"><div><b>18</b><span>位朋友参与</span></div><div><b>48</b><span>张现场照片</span></div><div><b>3</b><span>份共享文件</span></div><div><b>5</b><span>条便签与链接</span></div></div><div class="notice">内容保留至 <b>9 月 10 日 23:00</b>。<br>到期后将自动删除，请提前带走回忆。</div><div class="end-actions"><button class="primary" onclick="exportDemo()">↓ 导出房间内容（主持人）</button><button onclick="filter='全部';nav('guest');toast('演示导航：查看现场页面')">回看今晚的照片</button></div>`,false))}
function share(){if(closed){toast('房间已结束，无法继续分享');return}modal('<h2>把现场分享给大家</h2><p>内容对房间成员可见，照片精选后会上大屏。</p><div class="dialog-options"><button onclick="dialog.close();document.querySelector(\'#file\').click()">▧　选择照片（本地预览）</button><button onclick="noteForm()">▤　写一条便签</button><button onclick="linkForm()">↗　分享链接</button></div>')}
function noteForm(){document.querySelector('#dialogbody').innerHTML='<h2>写一条便签</h2><form onsubmit="event.preventDefault();saveNote()"><label class="field" for="note">想告诉大家什么？</label><textarea id="note" rows="4" maxlength="2000" required placeholder="比如：合照在餐厅门口拍"></textarea><p>默认不上大屏。本地演示，刷新后清空。</p><button class="primary full">发布便签</button></form>'}
function saveNote(){const n=document.querySelector('#note').value.trim();if(!n){toast('请先写一点内容');return}notes.unshift(n);filter='资料';dialog.close();nav('guest');render();toast('便签已添加到本地演示')}
function linkForm(){document.querySelector('#dialogbody').innerHTML='<h2>分享链接</h2><form onsubmit="event.preventDefault();saveLink()"><label class="field" for="url">链接地址</label><input id="url" type="url" required placeholder="https://"><p>仅支持 HTTP / HTTPS。本地演示不抓取网页。</p><button class="primary full">分享链接</button></form>'}
function saveLink(){const u=new URL(document.querySelector('#url').value);if(!['https:','http:'].includes(u.protocol)){toast('请使用 HTTP 或 HTTPS 链接');return}notes.unshift(u.href);filter='资料';dialog.close();nav('guest');render();toast('链接已添加到本地演示')}
function invite(){modal('<h2>邀请大家加入</h2><img class="qr" src="assets/qr.svg" alt="演示二维码" style="margin:18px auto"><h2 style="text-align:center">7K3P M9</h2><p>二维码指向 example 演示域名，不能加入真实房间。正式产品由可访问的部署地址生成。</p>')}
function settings(){modal('<h2>房间设置</h2><p>周末小聚 · 今晚 23:00 结束</p><div class="resource">上屏策略 <b style="float:right">主持人精选</b></div><div class="resource">内容保留 <b style="float:right">结束后 24 小时</b></div><div class="resource">房间容量 <b style="float:right">2 GB</b></div><p>配置说明预览。完整规则见开发设计文档。</p>')}
function members(){modal('<h2>房间参与者</h2>'+['熊猫 · 主持人','小林 · 在线','阿文 · 在线','小雨 · 在线'].map(n=>`<div class="resource">${n}</div>`).join('')+'<p>示例成员列表 · 总计 12 人在线</p>')}
function closeRoom(){modal('<h2>结束这次相聚？</h2><p>结束后停止分享，已有成员可查看到 9 月 10 日 23:00。你仍然可以导出内容。</p><button class="primary full" onclick="closed=true;dialog.close();nav(\'end\')">确认结束（演示）</button>')}
function exportDemo(){modal('<h2>导出房间内容</h2><p>正式产品会打包照片、文件、链接和便签。当前原型没有后端，只提供设计说明下载。</p><a href="../docs/RoomDeck-开发设计文档.md" download><button class="primary full">下载开发设计文档</button></a>')}
document.querySelector('#file').addEventListener('change',e=>{let files=[...e.target.files];for(const f of files.slice(0,20)){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>20*1024*1024){toast('请使用 20 MB 以内的 JPEG、PNG 或 WebP');continue}localPhotos.unshift({src:URL.createObjectURL(f),name:nickname,title:f.name})}filter='照片';nav('guest');render();toast('已加入本地预览，文件未上传到服务器');e.target.value=''})
function render(){const route=location.hash.slice(1)||'host';document.querySelectorAll('.previewbar nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));app.innerHTML=({join,guest,host,display,poll,end}[route]||host)();document.title='RoomDeck · '+({join:'加入房间',guest:'手机现场',host:'主持人控制台',display:'公共大屏',poll:'投票预览',end:'结束回顾'}[route]||'设计预览')}
if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');window.addEventListener('hashchange',render);render();

